package local.cleartv.mobile;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

final class Network {
    static final Map<String,JSONObject> known=new ConcurrentHashMap<>();static volatile long knownAt;
    static boolean local(String ip){try{String[] a=ip.split("\\.");if(a.length!=4)return false;int[] n=new int[4];for(int i=0;i<4;i++){if(!a[i].matches("[0-9]{1,3}"))return false;n[i]=Integer.parseInt(a[i]);if(n[i]>255)return false;}return n[0]==10||n[0]==192&&n[1]==168||n[0]==172&&n[1]>=16&&n[1]<=31;}catch(Exception e){return false;}}
    static byte[] read(InputStream source,int max)throws IOException{try(InputStream in=source;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Response too large");out.write(b,0,n);}return out.toByteArray();}}
    static String get(String url,int timeout)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(timeout);c.setReadTimeout(timeout);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("Service did not respond");return new String(read(c.getInputStream(),4*1024*1024),"UTF-8");}finally{c.disconnect();}}
    static JSONObject probeSamsung(String ip)throws Exception{if(!local(ip))throw new IOException("Enter a private local IPv4 address");JSONObject d=new JSONObject(get("http://"+ip+":8001/api/v2/",1200)).optJSONObject("device");if(d==null||!d.has("modelName"))throw new IOException("No compatible Samsung TV found");return new JSONObject().put("ip",ip).put("brand","samsung").put("name",d.optString("name","Samsung TV")).put("model",d.optString("modelName")).put("os",d.optString("OS")).put("osVersion",d.optString("osVersion",d.optString("TizenVersion","")));}
    static JSONObject probe(String ip)throws Exception{if(!local(ip))throw new IOException("Enter a private local IPv4 address");try{return AndroidTv.probe(ip);}catch(Exception ignored){}try{return probeSamsung(ip);}catch(Exception ignored){}List<JSONObject> lg=LgDiscovery.discover(ip);if(!lg.isEmpty())return lg.get(0);if(System.currentTimeMillis()-knownAt<120000&&known.containsKey(ip))return new JSONObject(known.get(ip).toString());throw new IOException("التلفزيون لم يعلن خدمة شبكة مدعومة. شغّله وتأكد من نفس الشبكة، وفعّل التحكم من الموبايل أو مشاركة الوسائط إن كانت متاحة.");}
    static String phoneIP(){try{Enumeration<NetworkInterface> it=NetworkInterface.getNetworkInterfaces();while(it.hasMoreElements()){NetworkInterface nic=it.nextElement();if(!nic.isUp()||nic.isLoopback())continue;Enumeration<InetAddress> addresses=nic.getInetAddresses();while(addresses.hasMoreElements()){InetAddress a=addresses.nextElement();if(a instanceof Inet4Address&&local(a.getHostAddress()))return a.getHostAddress();}}}catch(Exception ignored){}return "";}
    static JSONArray discover(android.content.Context context)throws Exception{android.net.wifi.WifiManager wifi=(android.net.wifi.WifiManager)context.getApplicationContext().getSystemService(android.content.Context.WIFI_SERVICE);android.net.wifi.WifiManager.MulticastLock lock=wifi==null?null:wifi.createMulticastLock("tvmorph-discovery");try{if(lock!=null){lock.setReferenceCounted(false);lock.acquire();}return discoverUnlocked(context);}finally{if(lock!=null&&lock.isHeld())lock.release();}}
    static JSONArray discoverUnlocked(android.content.Context context)throws Exception{known.clear();String own=phoneIP();if(own.isEmpty())throw new IOException("Connect your phone to the same Wi-Fi as the TV");String prefix=own.substring(0,own.lastIndexOf('.')+1);ExecutorService pool=Executors.newFixedThreadPool(20);Future<List<JSONObject>> android=pool.submit(()->AndroidDiscovery.discover(context));Future<List<JSONObject>> lg=pool.submit(()->LgDiscovery.discover(null));List<Future<JSONObject>> futures=new ArrayList<>();for(int i=1;i<255;i++){final String ip=prefix+i;if(ip.equals(own))continue;futures.add(pool.submit(()->{try{for(int port:AndroidTv.PORTS)try(Socket a=new Socket()){a.connect(new InetSocketAddress(ip,port),180);return AndroidTv.probe(ip);}catch(Exception ignored){}try(Socket samsung=new Socket()){samsung.connect(new InetSocketAddress(ip,8001),180);return probeSamsung(ip);}}catch(Exception e){return null;}}));}JSONArray result=new JSONArray();try{for(Future<JSONObject> f:futures){JSONObject tv=f.get(20,TimeUnit.SECONDS);if(tv!=null){result.put(tv);known.put(tv.getString("ip"),tv);knownAt=System.currentTimeMillis();}}try{for(JSONObject tv:lg.get(8,TimeUnit.SECONDS)){if(!known.containsKey(tv.getString("ip")))result.put(tv);known.putIfAbsent(tv.getString("ip"),tv);knownAt=System.currentTimeMillis();}}catch(Exception ignored){}try{for(JSONObject tv:android.get(6,TimeUnit.SECONDS)){boolean exists=false;for(int i=0;i<result.length();i++)if(result.getJSONObject(i).getString("ip").equals(tv.getString("ip")))exists=true;if(!exists){result.put(tv);known.put(tv.getString("ip"),tv);knownAt=System.currentTimeMillis();}}}catch(Exception ignored){}}finally{pool.shutdownNow();}return result;}
}
